<?php
namespace Core;require_once __DIR__.'/Guard.php';ml_guard_shield(__FILE__);class StaticGen{private static $lastStats=array('built'=>0,'failed'=>0,'locked'=>false);public static function outDir(){return __DIR__.'/../uisc';}public static function buildAll(){$a=self::outDir();if(!@is_dir($a)&&!@mkdir($a,0755,true)&&!is_dir($a)){self::$lastStats=array('built'=>0,'failed'=>1,'locked'=>false);return 0;}$b=@fopen($a.'/.build.lock','c');if(!$b||!@flock($b,LOCK_EX|LOCK_NB)){if($b){@fclose($b);}self::$lastStats=array('built'=>0,'failed'=>0,'locked'=>true);return 0;}$c=0;$d=0;try{foreach(CacheStore::allRows()as $e){try{if(self::writePage($a,(int)$e['id'],Views::renderItemPage($e))){$c++;}else{$d++;}}catch(\Throwable $f){$d++;}}}catch(\Throwable $f){$d++;}finally{@flock($b,LOCK_UN);@fclose($b);}self::$lastStats=array('built'=>$c,'failed'=>$d,'locked'=>false);return $c;}public static function buildOne($a){$b=self::outDir();if(!@is_dir($b)&&!@mkdir($b,0755,true)&&!is_dir($b)){return false;}$c=CacheStore::getRowById($a);if(!$c){return false;}$d=self::writePage($b,(int)$a,Views::renderItemPage($c));self::$lastStats=array('built'=>$d?1:0,'failed'=>$d?0:1,'locked'=>false);return $d;}public static function deleteOne($a){$b=self::outDir().'/'.(int)$a.'.html';return@unlink($b)||!is_file($b);}private static function writePage($a,$b,$c){$d=$a.'/'.$b.'.html';$e=$d.'.'.(function_exists('getmypid')?getmypid():0).'.'.bin2hex(random_bytes(4)).'.tmp';if(@file_put_contents($e,$c,LOCK_EX)===false){@unlink($e);return false;}if(!@rename($e,$d)){@unlink($e);return false;}return true;}}